pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const users = pm.response.json();

pm.test("Response contains user data", function () {
    pm.expect(users).to.be.an("array");
    pm.expect(users.length).to.be.greaterThan(0);
});

pm.test("Each user has id, name and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
});

// Extract and store user ID
const userId = users[0].id;
pm.collectionVariables.set("userId", userId);

// Store the complete user object
pm.collectionVariables.set(
    "userObject",
    JSON.stringify(users[0])
);

console.log("Stored User ID:", userId);
console.log("Stored User Object:", users[0]);

const randomNumber = Date.now();

const userObject = JSON.parse(
    pm.collectionVariables.get("userObject")
);

userObject.name = `Updated User ${randomNumber}`;
userObject.email = `updated.${randomNumber}@example.com`;
userObject.company.name = `Updated Company ${randomNumber}`;

pm.variables.set("requestBody", JSON.stringify(userObject));

console.log("Request Body:", userObject);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const response = pm.response.json();
const storedId = pm.collectionVariables.get("userId");

pm.test("Returned ID matches stored ID", function () {
    pm.expect(response.id).to.eql(Number(storedId));
});

pm.test("Phone field is not empty", function () {
    pm.expect(response.phone).to.exist;
    pm.expect(response.phone).to.not.be.empty;
});
